import React, { useState } from 'react';

import cn from 'clsx';
import { useNavigate } from 'react-router-dom';

import { success } from '@helpers/notificationHelper';
import PohAlert from '@ui-kit/Alert';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import PohInput, { InputTypes } from '@ui-kit/Input';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';

import { addRecipeAsync } from '../../@services/recipes.service';
import { IAddRecipeDTO } from '../../@types/recipes.backTypes';
import SelectRecipeCategory from '../SelectRecipeCategory';

interface IRecipeAddProps {}

const RecipeAdd: React.FC<IRecipeAddProps> = () => {
  const [isSaving, setIsSaving] = React.useState(false);
  const [err, setErr] = React.useState<Error>();
  const navigate = useNavigate();
  const [formData, setFormData] = useState<IAddRecipeDTO>({
    id_category: '1',
    name_recipe: '',
    promo_text: '',
    text: '',
    water_count: null,
    gas_count: null,
    cooking_time: null,
  });

  const submitFormHandler = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      setIsSaving(true);
      await addRecipeAsync(formData).then((newRecipe) => {
        success('Рецепт успешно добавлен');
        navigate(`/recipes/${newRecipe.id}`);
      });
    } catch (er) {
      setErr(er as Error);
    } finally {
      setIsSaving(false);
    }
  };

  const handleInputChange = (field: keyof IAddRecipeDTO) => (value: string) => {
    setFormData((fd) => ({
      ...fd,
      [field]: value,
    }));
  };

  if (err) {
    return <PohAlert>{err.message}</PohAlert>;
  }

  return (
    <form onSubmit={submitFormHandler} className={cn('mt-4', 'qa-hiking-base-info-form')}>
      <PohRow className="mb-2">
        <PohCol sm={12}>
          <SelectRecipeCategory
            value={+formData.id_category}
            onChange={(v) => handleInputChange('id_category')(v?.id ? v.id.toString() : '1')}
          />
        </PohCol>
      </PohRow>
      <PohRow className="mb-2">
        <PohCol sm={12}>
          <PohInput
            horizontal
            label="Название"
            placeholder="Название рецепта"
            required
            value={formData.name_recipe}
            name="name_recipe"
            id="name_recipe"
            onChange={handleInputChange('name_recipe')}
            autoFocus
            labelClassName="text-end"
          />
        </PohCol>
      </PohRow>
      <PohRow className="mb-2">
        <PohCol sm={12}>
          <PohInput
            horizontal
            type={InputTypes.textarea}
            label="Краткое описание"
            placeholder="Краткое описание рецепта (тизер)"
            required
            value={formData.promo_text}
            name="recipe-promo_text"
            id="recipe-promo_text"
            onChange={handleInputChange('promo_text')}
            labelClassName="text-end"
          />
        </PohCol>
      </PohRow>
      <PohRow className="mb-2">
        <PohCol sm={12}>
          <PohInput
            horizontal
            type={InputTypes.textarea}
            label="Полное описание"
            placeholder="Полное описание рецепт"
            value={formData.text}
            name="recipe-text"
            id="recipe-text"
            onChange={handleInputChange('text')}
            labelClassName="text-end"
          />
        </PohCol>
      </PohRow>
      <PohRow className="mb-2">
        <PohCol sm={2}></PohCol>

        <PohCol sm={3}>
          <PohInput
            type={InputTypes.number}
            label="Приготовление (минут)"
            value={formData.cooking_time ? formData.cooking_time.toString() : ''}
            name="recipe-time"
            id="recipe-time"
            onChange={handleInputChange('cooking_time')}
          />
        </PohCol>
        <PohCol sm={3}>
          <PohInput
            type={InputTypes.number}
            label="Кол-во воды (мл)"
            value={formData.water_count ? formData.water_count.toString() : ''}
            name="recipe-water_count"
            id="recipe-water_count"
            onChange={handleInputChange('water_count')}
          />
        </PohCol>
        <PohCol sm={3}>
          <PohInput
            type={InputTypes.number}
            label="Кол-во газа (г)"
            value={formData.gas_count ? formData.gas_count.toString() : ''}
            name="recipe-gas_count"
            id="recipe-gas_count"
            onChange={handleInputChange('gas_count')}
          />
        </PohCol>
      </PohRow>
      <PohRow className="mb-4 mt-2">
        <PohCol sm={2} />
        <PohCol sm={10}>
          <PohButton
            variant={ButtonVariant.Primary}
            disabled={isSaving}
            onClick={() => {}}
            className="w-100"
            type="submit"
          >
            Добавить
          </PohButton>
        </PohCol>
      </PohRow>
    </form>
  );
};

export default RecipeAdd;
