import React from 'react';

import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';

import RecipeAdd from '../components/RecipeApp';

interface IRecipeAddPage {}

const RecipeAddPage: React.FC<IRecipeAddPage> = () => {
  return (
    <PohContainer>
      <PohRow>
        <PohCol
          lg={{ span: 8, offset: 2 }}
          md={{ span: 10, offset: 1 }}
          sm={{ span: 12, offset: 0 }}
        >
          <PohRow>
            <PohCol sm={2} />
            <PohCol sm={10}>
              <h2>Новый рецепт</h2>
            </PohCol>
          </PohRow>
        </PohCol>
      </PohRow>
      <PohRow>
        <PohCol
          lg={{ span: 8, offset: 2 }}
          md={{ span: 10, offset: 1 }}
          sm={{ span: 12, offset: 0 }}
        >
          <RecipeAdd />
        </PohCol>
      </PohRow>
    </PohContainer>
  );
};

export default RecipeAddPage;
